      "Jar B (500g @ \u20b9225) = \u20b9225 / 5 = \u20b945 per 100g.",
      "Notice that Jar A is actually \u20b95 cheaper per 100g despite being in a smaller jar!",
      "Choose the product that gives maximum quality and quantity for your family's budget."
